/**
 * Addresses and browser history. Each tool has its own page (routes.js,
 * generated by scripts/build-pages.mjs). On any page, the editor and the batch
 * workspace are history entries stacked on the page's own entry: Back and
 * Forward move between views instead of leaving the site, the address names
 * the tool in use, and a reload opens that tool's page. Documents live only in
 * memory, so a reload starts on the landing.
 *
 * The editor shows the views (restoreView in editor.js; app.js only finishes
 * the landing view). This module, which imports only editor-core.js and
 * routes.js, records them, so any module can record a view without importing
 * an entry module back.
 */

import { $, names, ui } from './editor-core.js';
import { TOOL_PAGES } from './routes.js';

const siteRoot = new URL('./', import.meta.url);
/** The page as it was loaded: its address and title. */
export const landingView = { address: location.pathname, title: document.title };
let restoringView = false;
export const viewDepth = () => Number(history.state?.depth) || 0;
function viewAddress(view) {
  const slug = TOOL_PAGES[view === 'batch' ? 'batch' : ui.tool];
  return view === 'landing' || !slug ? landingView.address : new URL(slug + '/', siteRoot).pathname;
}
export function viewTitle(view) {
  if (view === 'landing') return landingView.title;
  return (view === 'batch' ? 'Batch & presets' : names[ui.tool]) + ' — QFT PDF';
}
/** Record the visible view: a new entry for a new view, a replacement when only the tool changes. */
export function recordView(view) {
  if (restoringView) return;
  const current = history.state?.view || 'landing';
  const entry = { view, depth: viewDepth() + (view === current ? 0 : 1) };
  if (view === current) history.replaceState(entry, '', viewAddress(view));
  else history.pushState(entry, '', viewAddress(view));
  ui.shownDepth = entry.depth;
  document.title = viewTitle(view);
}
/** The landing view is showing: its title, and focus at the top or at the tools (ui.landingFocus). */
export function finishLanding() {
  document.title = landingView.title;
  const focus = ui.landingFocus;
  ui.landingFocus = null;
  if (focus === 'tools') {
    $('#tools-title').focus({ preventScroll: true });
    const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
    setTimeout(() => $('#tools').scrollIntoView({ behavior: reduce ? 'auto' : 'smooth' }), 0);
  } else {
    $('#landing-title').focus({ preventScroll: true });
    window.scrollTo(0, 0);
  }
}
/** Run `show` for a view the browser is going back or forward to: nothing is recorded meanwhile. */
export function restoring(show) {
  restoringView = true;
  try {
    show();
  } finally {
    restoringView = false;
  }
}
